210→// ── Command ────────────────────────────────────────────────────────────────────

export default defineCommand({
  meta: {
    name: "review",
    description: [
      "Multi-tier skill review (structure → heuristics → LLM → sessions). Includes Session health.",
      "",
      "Start here: dora review --quick",
      "Examples:",
220→      "  dora review --quick .",
      "  dora review --quick --json",
      "  dora review --deep .",
      "Exit: 0 clean · 1 issues · 2 could not run",
      "Map: dora --help --json",
    ].join("\n"),
  },
  args: {
    path: { type: "positional", description: "Skill dir or project root", required: false, default: "." },
    quick: { type: "boolean", description: "Tiers 1–2 only (structure + heuristics, no LLM)", default: false },
230→    deep: { type: "boolean", description: "Require LLM tier; exit 2 if no judge", default: false },
    sessions: { type: "boolean", description: "Require the session-evidence tier (exit 2 if no recent sessions)", default: false },
    all: { type: "boolean", description: "Review every artifact (skip the 10-item question)", default: false },
    "fail-on": { type: "string", description: "Exit 1 trigger: error (default) | warning", default: "error" },
    format: { type: "string", description: "Output format: table | json", default: "table" },
    json: { type: "boolean", description: "Alias for --format json", default: false },
    ci: { type: "boolean", description: "Machine mode (implies --format json)", default: false },
    cwd: { type: "string", description: "Working directory override" },
  },
  async run({ args }) {
240→    const mode = resolveOutputMode({ format: args.format as string, ci: args.ci as boolean, json: args.json as boolean });
    preflight(
      mode,
      reviewPreflightMessage({
        quick: args.quick as boolean,
        deep: args.deep as boolean,
      }),
    );
    // Resolve --cwd to an absolute path: it's hashed into the memory
    // project slug (getProjectSlug), so a relative string here would give
250→    // the same physical project two different slugs depending on how the
    // caller happened to spell --cwd.
    const root = args.cwd ? resolve(args.cwd as string) : process.cwd();
    const target = resolve(root, (args.path as string) || ".");
    const useAll = args.all as boolean;
    const targets = listReviewTargets(target, root);
    let limit: number | undefined;
    if (targets.length > REVIEW_DEFAULT_LIMIT && !useAll) {
      if (shouldAskReviewLimit({ format: mode.format, all: useAll, agent: isAgentCaller() })) {
        const choice = await select({
260→          message: `Found ${targets.length} artifacts. Review can call an LLM for each one.`,
          options: [
            { value: "limit", label: `Review first ${REVIEW_DEFAULT_LIMIT}` },
            { value: "all", label: `Review all ${targets.length}` },
            { value: "cancel", label: "Cancel" },
          ],
          output: process.stderr,
        });
        if (isCancel(choice) || choice === "cancel") {
          ui.dim("  Cancelled.");
270→          await exit(0);
