  if (opts.limit != null) targets = targets.slice(0, opts.limit);

  const loadedSessions = opts.quick ? undefined : (opts.loadedSessions ?? loadRecentSessions(cwd));
  const per = { ...opts, cwd, ...(loadedSessions ? { loadedSessions } : {}) };
  const one = (target: string) =>
    isSkillDir(target) ? reviewSkill(target, per) : reviewMemoryFile(target, per);

  const stamp = (r: ReviewResult): ReviewResult => {
    if (!isSkillDir(r.path)) return r;
    const root = pluginRoot(r.path, cwd);
    return root ? { ...r, pluginOwned: true, pluginRoot: root } : r;
  };

  const health = loadedSessions ? collectSessionHealth(loadedSessions) : undefined;
  const withHealth = (r: ReviewResult): ReviewResult =>
    health ? { ...r, sessionHealth: health } : r;

  if (opts.quick) return Promise.all(targets.map(one)).then((rows) => rows.map(stamp));
  const results: ReviewResult[] = [];
  for (const target of targets) results.push(withHealth(stamp(await one(target))));
  return results;
}

