      skillName: "demo",
      skillContent: "x",
      scenarios: [],
      agent: { command: "grok" },
      evalCfg: {},
      deps: { runSession: async () => { throw new Error("must not spawn"); } },
    });
    expect(findings).toEqual([]);
  });

