    const prompt = buildLiveScorePrompt("trace", {
      when: "deploy",
      expect: "Refuse",
      must_not: "Ship",
    });
    expect(prompt).toContain("Expect: Refuse");
    expect(prompt).toContain("Must not: Ship");
    expect(prompt).toContain("trace");
  });
});

